settings.global_custom_css:
#addonId .sppb-addon-title strong {
	font-weight: 700;
}
#addonId .sppb-addon-content {
  margin-left: 25px;
  padding-left: 22px;
  position:relative;
}
#addonId .sppb-addon-content:after {
  content: "";
  position:absolute;
  width:4px;
  height:100%;
  top: 0;
  left:0;
  border-radius: 2px;
  background-color: #191e29;
}
